FROM warehouse


        AND whAddress LIKE CONCAT('%', #{searchDTO.whAddress}, '%')


        AND whName = #{searchDTO.whName}


        AND whGrade = #{searchDTO.whGrade}


ORDER BY whName ASC
LIMIT #{criteria.skip}, #{criteria.amount}

